45 #pragma once
46 #ifndef AI_STREAMREADER_H_INCLUDED
47 #define AI_STREAMREADER_H_INCLUDED
48 
49 #ifdef __GNUC__
50 #   pragma GCC system_header
51 #endif
52 
53 #include <assimp/ByteSwapper.h>
54 #include <assimp/Exceptional.h>
55 #include <assimp/IOStream.hpp>
56 
57 #include <memory>
58 
59 namespace Assimp {
60 
61 // --------------------------------------------------------------------------------------------
70 // --------------------------------------------------------------------------------------------
71 template <bool SwapEndianess = false, bool RuntimeSwitch = false>
72 class StreamReader {
73 public:
74     using diff = size_t;
75     using pos = size_t;
76 
77     // ---------------------------------------------------------------------
89     StreamReader(std::shared_ptr<IOStream> stream, bool le = false) :
90             mStream(stream),
91             mBuffer(nullptr),
92             mCurrent(nullptr),
93             mEnd(nullptr),
94             mLimit(nullptr),
95             mLe(le) {
96         ai_assert(stream);
97         InternBegin();
98     }
99 
100     // ---------------------------------------------------------------------
101     StreamReader(IOStream *stream, bool le = false) :
102             mStream(std::shared_ptr<IOStream>(stream)),
103             mBuffer(nullptr),
104             mCurrent(nullptr),
105             mEnd(nullptr),
106             mLimit(nullptr),
107             mLe(le) {
108         ai_assert(nullptr != stream);
109         InternBegin();
110     }
111 
112     // ---------------------------------------------------------------------
113     ~StreamReader() {
114         delete[] mBuffer;
115     }
116 
117     // deprecated, use overloaded operator>> instead
118 
119     // ---------------------------------------------------------------------
121     float GetF4() {
122         return Get<float>();
123     }
124 
125     // ---------------------------------------------------------------------
127     double GetF8() {
128         return Get<double>();
129     }
130 
131     // ---------------------------------------------------------------------
133     int16_t GetI2() {
134         return Get<int16_t>();
135     }
136 
137     // ---------------------------------------------------------------------
139     int8_t GetI1() {
140         return Get<int8_t>();
141     }
142 
143     // ---------------------------------------------------------------------
145     int32_t GetI4() {
146         return Get<int32_t>();
147     }
148 
149     // ---------------------------------------------------------------------
151     int64_t GetI8() {
152         return Get<int64_t>();
153     }
154 
155     // ---------------------------------------------------------------------
157     uint16_t GetU2() {
158         return Get<uint16_t>();
159     }
160 
161     // ---------------------------------------------------------------------
163     uint8_t GetU1() {
164         return Get<uint8_t>();
165     }
166 
167     // ---------------------------------------------------------------------
169     uint32_t GetU4() {
170         return Get<uint32_t>();
171     }
172 
173     // ---------------------------------------------------------------------
175     uint64_t GetU8() {
176         return Get<uint64_t>();
177     }
178 
179     // ---------------------------------------------------------------------
181     size_t GetRemainingSize() const {
182         return (unsigned int)(mEnd - mCurrent);
183     }
184 
185     // ---------------------------------------------------------------------
189     size_t GetRemainingSizeToLimit() const {
190         return (unsigned int)(mLimit - mCurrent);
191     }
192 
193     // ---------------------------------------------------------------------
195     void IncPtr(intptr_t plus) {
196         mCurrent += plus;
197         if (mCurrent > mLimit) {
198             throw DeadlyImportError("End of file or read limit was reached");
199         }
200     }
201 
202     // ---------------------------------------------------------------------
204     int8_t *GetPtr() const {
205         return mCurrent;
206     }
207 
208     // ---------------------------------------------------------------------
214     void SetPtr(int8_t *p) {
215         mCurrent = p;
216         if (mCurrent > mLimit || mCurrent < mBuffer) {
217             throw DeadlyImportError("End of file or read limit was reached");
218         }
219     }
220 
221     // ---------------------------------------------------------------------
225     void CopyAndAdvance(void *out, size_t bytes) {
226         int8_t *ur = GetPtr();
227         SetPtr(ur + bytes); // fire exception if eof
228 
229         ::memcpy(out, ur, bytes);
230     }
231 
233     int GetCurrentPos() const {
234         return (unsigned int)(mCurrent - mBuffer);
235     }
236 
237     void SetCurrentPos(size_t pos) {
238         SetPtr(mBuffer + pos);
239     }
240 
241     // ---------------------------------------------------------------------
248     unsigned int SetReadLimit(unsigned int _limit) {
249         unsigned int prev = GetReadLimit();
250         if (UINT_MAX == _limit) {
251             mLimit = mEnd;
252             return prev;
253         }
254 
255         mLimit = mBuffer + _limit;
256         if (mLimit > mEnd) {
257             throw DeadlyImportError("StreamReader: Invalid read limit");
258         }
259         return prev;
260     }
261 
262     // ---------------------------------------------------------------------
265     unsigned int GetReadLimit() const {
266         return (unsigned int)(mLimit - mBuffer);
267     }
268 
269     // ---------------------------------------------------------------------
272     void SkipToReadLimit() {
273         mCurrent = mLimit;
274     }
275 
276     // ---------------------------------------------------------------------
278     template <typename T>
279     StreamReader &operator>>(T &f) {
280         f = Get<T>();
281         return *this;
282     }
283 
284     // ---------------------------------------------------------------------
286     template <typename T>
287     T Get() {
288         if (mCurrent + sizeof(T) > mLimit) {
289             throw DeadlyImportError("End of file or stream limit was reached");
290         }
291 
292         T f;
293         ::memcpy(&f, mCurrent, sizeof(T));
294         Intern::Getter<SwapEndianess, T, RuntimeSwitch>()(&f, mLe);
295         mCurrent += sizeof(T);
296 
297         return f;
298     }
299 
300 private:
301     // ---------------------------------------------------------------------
302     void InternBegin() {
303         if (nullptr == mStream) {
304             throw DeadlyImportError("StreamReader: Unable to open file");
305         }
306 
307         const size_t filesize = mStream->FileSize() - mStream->Tell();
308         if (0 == filesize) {
309             throw DeadlyImportError("StreamReader: File is empty or EOF is already reached");
310         }
311 
312         mCurrent = mBuffer = new int8_t[filesize];
313         const size_t read = mStream->Read(mCurrent, 1, filesize);
314         // (read < s) can only happen if the stream was opened in text mode, in which case FileSize() is not reliable
315         ai_assert(read <= filesize);
316         mEnd = mLimit = &mBuffer[read - 1] + 1;
317     }
318 
319 private:
320     std::shared_ptr<IOStream> mStream;
321     int8_t *mBuffer;
322     int8_t *mCurrent;
323     int8_t *mEnd;
324     int8_t *mLimit;
325     bool mLe;
326 };
327 
328 // --------------------------------------------------------------------------------------------
329 // `static` StreamReaders. Their byte order is fixed and they might be a little bit faster.
330 #ifdef AI_BUILD_BIG_ENDIAN
331 typedef StreamReader<true> StreamReaderLE;
332 typedef StreamReader<false> StreamReaderBE;
333 #else
334 typedef StreamReader<true> StreamReaderBE;
335 typedef StreamReader<false> StreamReaderLE;
336 #endif
337 
338 // `dynamic` StreamReader. The byte order of the input data is specified in the
339 // c'tor. This involves runtime branching and might be a little bit slower.
340 typedef StreamReader<true, true> StreamReaderAny;
341 
342 } // end namespace Assimp
343 
344 #endif // !! AI_STREAMREADER_H_INCLUDED
